content.text:
{
  "name": "ASCII STL 文件写出器",
  "name_en": "ASCII STL Writer",
  "manufacturer": "",
  "description": "用于将由三角形或四边形面片组成的三维几何体导出为 ASCII STL 文件的软件工具，常用于数控加工、3D 建模或实验装置零件的几何数据保存与交换。",
  "description_en": "A software tool for exporting 3D geometry composed of triangular or quadrilateral faces to ASCII STL files, commonly used to save and exchange geometry for CNC machining, 3D modeling, or laboratory fixture parts.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭当前 STL 文件输出。",
      "description_en": "Close the current STL file output."
    },
    {
      "action_name": "auto-add_face",
      "description": "向 STL 输出中添加一个由 3 个或 4 个顶点组成的面片。",
      "description_en": "Add one face with 3 or 4 vertices to the STL output."
    },
    {
      "action_name": "auto-add_faces",
      "description": "向 STL 输出中批量添加多个面片。",
      "description_en": "Add multiple faces to the STL output."
    }
  ],
  "tag_hints": [
    "ASCII STL",
    "STL export",
    "3D mesh writing",
    "CAD/CAM data",
    "3D geometry",
    "mesh face output"
  ]
}

